function field(string $name, string $label, string $value='', string $type='text', string $hint=''): void { ?>
<label class="field"><span><?=e($label)?></span><?php if($type==='textarea'): ?><textarea name="<?=e($name)?>" rows="4"><?=e($value)?></textarea><?php else: ?><input type="<?=e($type)?>" name="<?=e($name)?>" value="<?=e($value)?>"><?php endif; ?><?php if($hint): ?><small><?=e($hint)?></small><?php endif; ?></label>
<?php }
function imageField(string $name, string $current, string $remove, string $label): void { ?>
<div class="image-upload"><div class="image-preview"><?php if($current): ?><img src="<?=e($current)?>" alt="<?=e($label)?>"><?php else: ?><span class="image-placeholder">↥</span><?php endif; ?></div><div><label class="field"><span><?=e($label)?></span><small>JPG, PNG ou WebP · até 2 MB</small><input type="file" name="<?=e($name)?>" accept="image/jpeg,image/png,image/webp" data-image-input></label><small class="file-feedback" aria-live="polite"></small><?php if($current): ?><label class="check"><input type="checkbox" name="<?=e($remove)?>"> Remover imagem actual</label><?php endif; ?></div></div>
<?php } ?>
